from pathlib import Path
import json,re
r=Path(__file__).parent;rows=[]
def row(k,exposure,endpoint,compartment,result,limits,prior,decision,section,why,kind='primary',access='Primary abstract/metadata recovered; publisher full text and supplements not recovered.'):
 x=json.loads((r/'sources'/f'{k}.json').read_text());h=x['metadata'];authors=h['authorList']['author'];first=authors[0].get('lastName',h['authorString'].split(',')[0]);year=h['pubYear'];label=f'{first} et al. ({year})'
 rows.append(dict(citation_key=k,doi=x['doi'],title=re.sub('<[^>]+>','',h['title']),label=label,year=year,authors=[a.get('fullName','') for a in authors],publication_class=kind,intervention=exposure,endpoint=endpoint,tissue_specificity=compartment,result=result,limitations=limits,prior_review=prior,final_disposition=decision,section_placement=section,adjudication=why,type_a='Not a demonstrated biochemical dependency or dietary requirement.',type_b='Admitted only for the bounded circulating DHA signal proposition with DHA-specific supporting trial.' if k=='allaire_compared_2016' else 'No isolated substance admission from a mixture, food-level or transcript-only result; independently assess the precise protocol.',direct_derived='Direct for an admitted circulating-hormone response relative to PM8; not evidence of secretion flux. No precursor conversion asserted.' if decision.startswith('admit') else 'Not assigned to an unadmitted substance; transcript, plasma and systemic endpoints remain separate.',substance_identity=['dha-docosahexaenoic-acid','epa-eicosapentaenoic-acid'] if 'fish_oil' in k or 'rausch' in k else ['dha-docosahexaenoic-acid'] if 'canola' in k or 'allaire' in k else ['ala-alpha-linolenic-acid'] if 'flaxseed' in k else [],food_linkage='Existing EPA/DHA food-composition edges verified separately; no trial/food efficacy equivalence.' if 'fish_oil' in k or 'rausch' in k or 'allaire' in k else 'Fortified experimental oil has no matching canonical food record; ordinary canola oil is not equivalent.' if 'canola' in k else 'Existing flax-seeds food record resolves; ALA composition does not identify the active intervention constituent.' if 'flaxseed' in k else 'No substance-to-food relationship inferred from a dietary pattern or heterogeneous fibre class.',sec='Applicable to the exact Finding proposition; unresolved factors retained and no new numerical total forced.',source_url='https://doi.org/'+x['doi'],retrieval_scope=access,editorial_notice_check='No notice returned in Scite mandatory-study metadata; absence of a returned field is not proof that no correction exists.'))
row('rausch_omega3_adipokines_2021','31 RCTs, varied EPA/DHA doses, populations and duration; searches to June 2018.','Leptin, adiponectin and their ratio in blood.','circulating','18/31 reported lower leptin or higher adiponectin direction; 9 significant between-group results. Review did not pool effect sizes because distribution/reporting differed.','Secondary synthesis, not 31 independent confirmations of one formulation. Primary trial overlap retained; dose and population variability preclude universal efficacy.','No prior separate appraisal located; prior Wu synthesis covered overlapping trials.','evidence-only','Evidence & Audit','Supports recovery of primary trials and limits generalisation; no class-wide admission by vote count.','secondary','Full author-manuscript PDF recovered from Indiana University repository; Methods, risk-of-bias table and relevant results inspected. Supplement referenced but not recovered.')
row('gammelmark_fish_oil_adiponectin_2012','50 overweight adults randomised double-blind to 2 g/day fish oil (1.1 g marine n-3) or 2 g olive oil for 6 weeks; day-1 assessment.','Serum adiponectin and adipose/granulocyte fatty-acid incorporation; inflammatory markers.','circulating + adipose composition','Adiponectin difference +0.55 µg/mL (95% CI 0.02–1.08); adipose n-3 incorporation increased. No overall anti-inflammatory effect.','Incorporation is not secretion. Mixed EPA/DHA does not isolate EPA versus DHA; small effect, adiposity/clearance mediation unresolved.','Not separately appraised before; identifiable in previously retrieved Wu review, not proof of a prior source-level assessment.','support bounded DHA evidence; defer EPA-specific admission','Evidence & Audit','Oral delivery is demonstrated for the mixture. Previous blanket missing-delivery wording was too broad; local secretory mediation still unmeasured.')
row('baril_gravel_dha_canola_2015','114 adults with abdominal obesity plus another metabolic-syndrome criterion; five isoenergetic 4-week diet periods with 4-week washouts; oils 60 g/3000 kcal.','Plasma adiponectin; inflammatory transcripts in whole blood in subgroup 62.','circulating; blood-cell transcripts, not adipose','DHA-enriched high-oleic canola oil: +4.5% versus corn/safflower, +6.9% versus flax/safflower.','Published significant contrasts do not isolate DHA from the high-oleic carrier; no claimed superiority to every canola arm or generic oil/food equivalent.','No previous separate appraisal located.','evidence-only for tested formulation; supports contextual DHA assessment','Evidence & Audit','Attributable exposure is the tested oil diet. DHA-specific admission additionally relies on the separate ComparED trial, not this formulation alone.')
row('motlagh_flaxseed_adiponectin_2021','60 women aged 25–50 randomised to balanced diet plus 30 g/day milled brown flaxseed or raw milled rice for 12 weeks.','Serum adiponectin/leptin; anthropometry and lipids.','circulating, not tissue secretion','52 completed (29 flax/23 control). Higher adiponectin between groups; leptin contrast not significant. Weight and waist also changed.','Differential attrition, complete-case analysis and concurrent weight change; no constituent attribution or proven secretory mechanism. Adiponectin units retained as printed.','No previous separate appraisal located.','admit bounded food-level practice','3.2','A defined human food protocol measured an endocrine signal. Admission is limited to studied circulating response, not weight-independent mechanism or universal optimisation.',access='Complete primary PDF recovered from Chalmers; Methods, flow, Tables 1–3 and limitations inspected. No separate supplement identified.')
row('zeinabi_soluble_fibre_adipokines_2023','Systematic review/dose-response meta-analysis of soluble-fibre supplementation; searches through December 2021.','Serum leptin and adiponectin.','circulating','Overall adiponectin SMD −0.49 (95% CI −1.20,0.21), leptin −0.80 (−1.70,0.08); high heterogeneity.','Overall null is not proof of no effect. Borderline subgroup signals, heterogeneous preparations and dose modelling do not establish a generic PM8 fibre relationship.','No previous separate appraisal located.','reject general soluble-fibre endocrine claim; retain subtype candidates','Evidence Gaps / Evidence & Audit','No generic fibre Type A/B admission; cross-BRS benefits are not PM8 endocrine engagement.','secondary','Full primary review XML recovered through Europe PMC; methods, results and limitations inspected.')
row('stomby_diet_glucocorticoid_2015','49 overweight/obese postmenopausal women, Paleolithic-type versus Nordic-recommendation diet for 24 months.','SAT 11β-HSD1 mRNA at 6/24 months; oral-cortisone hepatic conversion and urinary metabolites.','adipose transcript; hepatic/systemic separately','Adipose transcript decreased at 6 and 24 months in both groups; hepatic conversion changed transiently. Both groups lost weight.','Not direct adipose enzyme activity or local cortisol-regeneration flux; diet composition and weight/energy effects not isolated.','Already retrieved and appraised in SF13 and prior full-rerun evidence matrix.','admit as qualification of existing dietary-weight-loss SOP','3.2','Extends the existing programme evidence to a local transcript endpoint without claiming measured regeneration or superiority of a named diet.')
row('stimson_diet_cortisol_2007','Two randomised crossovers: 17 obese men ad libitum for 4 weeks; 6 men isocaloric; high-fat/low-carbohydrate versus moderate fat/carbohydrate.','Tracer cortisol turnover, urinary metabolites and SAT 11β-HSD1 mRNA/activity.','systemic/hepatic and adipose','Systemic cortisol regeneration/inactivation changed; subcutaneous adipose mRNA and activity were unaffected.','Tissue-specific null bounds this diet protocol; does not exclude all diet effects or contradict different long-term transcript measurements.','Already appraised and retained in SF13 and EG1.','no local adipose intervention admission from this result','Evidence & Audit / Evidence Gaps','Systemic cortisol changes cannot substitute for adipose target engagement.')
row('allaire_compared_2016','154 adults randomised in double-blind crossover; 2.7 g/day EPA, 2.7 g/day DHA (90%-pure re-esterified triglyceride supplements), or corn oil for 10 weeks, 9-week washouts.','Circulating adiponectin and inflammatory/lipid endpoints.','circulating','DHA increased adiponectin more than EPA: +3.1% ±1.6% versus −1.2% ±1.7%, P<0.001 in primary abstract; Rausch reports DHA-control contrast.','No adipose secretion/receptor assay; selected population and supplement form; no ordinary-food, dose-equivalence or clinical benefit inferred.','Recovered through mandatory Rausch review; no previous separate appraisal located.','admit DHA Type B for scoped circulating response','3.1.1','DHA-specific oral exposure and endocrine signal modulation support the bounded Type B proposition. This is not evidence for tissue secretion or general improvement.')
row('abbasi_flaxseed_adipokines_2023','13 RCTs/15 arms, varied whole/ground flaxseed and oils; searches through December 2022.','Circulating leptin/adiponectin.','circulating','Pooled adiponectin was not significant; substantial heterogeneity and small-study effects. Whole-flax subgroup differed from oils.','Secondary synthesis overlaps primary trial. Subgroup findings cannot erase overall uncertainty; no full-class or isolated-ALA effect inferred.','Newly recovered during independent/counterevidence search.','qualifies bounded flaxseed practice; rejects broad efficacy claim','Evidence & Audit','Retain positive study and pooled uncertainty together; no duplicate independent replication credit.','secondary','Complete Europe PMC XML and Scite full-body portions recovered; methods/results/limitations reviewed.')
(r/'adjudication-matrix.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n');print(len(rows))
